   "lead": "La sezione della California dell'Associated General Contractors (AGC), insieme a importanti aziende di costruzioni come Clark, Turner e Hensel Phelps, ha costituito la Prime Pipeline Alliance. L'iniziativa ha l'obiettivo di offrire supporto e tutoraggio alle piccole imprese di subappalto locali e diversificate nel settore edile. Lo riferisce Construction Dive.",
