   "id": "zf1d831a2",
   "sez": "mondo",
   "titolo": "Come prevenire l'osteoporosi: dall'allenamento con i pesi agli alimenti ricchi di calcio",
   "orig": "How to prevent osteoporosis, from strength training to eating calcium-rich food",
   "lead": "L'osteoporosi è una condizione silenziosa che indebolisce le ossa, rendendole sottili, meno dense e più soggette a fratture a seguito di traumi minimi come una caduta banale, il sollevamento di un peso o un colpo di tosse. Per prevenirla, come spiega la dottoressa Edith Lau, presidente fondatrice della Asian Pacific Osteoporosis Foundation (APOF), è fondamentale combinare l'attività fisica basata sull'allenamento della forza e un'alimentazione adeguata ricca di calcio. Lo riferisce South China Morning Post – Cultura.",
   "more": [
    "L'osteoporosi colpisce prevalentemente le ossa dell'avambraccio, della spina dorsale e dell'anca. La prevenzione si basa sul rafforzamento della massa ossea durante la giovinezza e sul mantenimento della densità minerale in età adulta attraverso esercizio fisico regolare e un corretto apporto di nutrienti."
   ],
