   "lead": "Tre funzionari dell'ufficio del distretto di Nakanai, nella provincia della Nuova Britannia Occidentale, hanno partecipato al vertice sul turismo e alla fiera commerciale tenutisi la scorsa settimana a Port Moresby. L'evento ha rappresentato un'occasione per promuovere le risorse turistiche e le opportunità di sviluppo locale della regione. Lo riferisce Post-Courier.",
