   "titolo": "Pakistan, il governo riduce il prezzo della benzina e del gasolio",
   "orig": "Govt slashes petrol price by Rs5.16 per litre, high-speed diesel rate by Rs7.69",
   "lead": "Il governo pakistano ha annunciato una diminuzione dei prezzi dei carburanti, tagliando la benzina di 5,16 rupie al litro e il gasolio ad alta velocità (high-speed diesel) di 7,69 rupie al litro, nell'ambito del meccanismo di revisione periodica dei prezzi. Lo riferisce Dawn.",
   "more": [
    "Le variazioni dei prezzi dei carburanti regolate dai governi riflettono l'andamento del mercato petrolifero internazionale e dei tassi di cambio, incidendo direttamente sul costo della vita e sui costi logistici interni dei Paesi importatori."
   ],
