   "id": "zc75b2e01",
   "sez": "cultura",
   "titolo": "Il fenomeno delle design week tra crescita delle rassegne e riflessione sui rischi di omologazione",
   "orig": "Quante design week: croce e delizia",
   "lead": "Da Napoli a Torino, da Como a Catanzaro, il proliferare di manifestazioni e settimane del design solleva interrogativi e crescenti consapevolezze sui rischi legati alla moltiplicazione degli eventi. Secondo l'analisi del settore, le rassegne più riuscite sono quelle che radicano la propria identità nelle storie, nelle specificità e nelle persone dei luoghi, evitando di imitare acriticamente modelli consolidati o di trasformare le città in semplici scenografie. Lo riferisce Il Giornale dell'Architettura.",
   "more": [
    "La proliferazione di eventi legati al design e all'architettura nelle città italiane riflette la vitalità del settore creativo, ma impone anche una riflessione sulla sostenibilità urbana e sulla necessità di valorizzare le identità locali anziché replicare format standardizzati."
   ],
