   "lead": "La piattaforma Crunchyroll ha ampliato la propria offerta rendendo disponibili i video musicali legati a serie e franchise di successo come Haikyu!! e Daemons of the Shadow Realm. Le nuove pubblicazioni includono brani e collaborazioni con artisti e gruppi musicali giapponesi tra cui BURNOUT SYNDROMES e Vaundy. Lo riferisce Crunchyroll News.",
