   "orig": "Lithuanian FM calls for end to escalation amid drone attacks on Black Sea ships - The Baltic Times",
   "lead": "Il ministro degli Esteri lituano Kestutis Budrys ha lanciato un appello per porre fine all'escalation in seguito al moltiplicarsi degli attacchi con droni contro le navi commerciali in transito nel Mar Nero. La presa di posizione evidenzia la crescente preoccupazione internazionale per la sicurezza della navigazione marittima nella regione. Lo riferisce The Baltic Times.",
