   "sez": "spazio",
   "titolo": "Urano e Nettuno potrebbero avere storie d'origine differenti, rivelano analisi atmosferiche",
   "orig": "Planetary 'twins' Uranus and Neptune may have different origin stories",
   "lead": "Un team internazionale di scienziati, analizzando indirettamente le profondità delle atmosfere di Urano e Nettuno, ha scoperto una marcata differenza nella loro composizione chimica: Nettuno risulta più ricco di ossigeno rispetto a Urano. I risultati suggeriscono che i due giganti di ghiaccio si siano formati in regioni distinte del sistema solare primordiale prima di raggiungere le attuali orbite, mettendo in discussione la teoria secondo cui sarebbero pianeti gemelli con un'origine comune. Lo riferisce Phys.org – Spazio.",
   "more": [
    "Lo studio della composizione atmosferica dei giganti ghiacciati aiuta gli astronomi a comprendere i processi di migrazione planetaria e la distribuzione dei materiali volatili nelle prime fasi di formazione del sistema solare."
   ],
