   "sez": "salute",
   "titolo": "Il Ministero della Salute potenzia la diagnosi della malaria in Sierra Leone",
   "orig": "Health Ministry Steps Up Efforts to Improve Malaria Diagnosis Across Sierra Leone",
   "lead": "Il Ministero della Salute della Sierra Leone ha concluso un corso di aggiornamento intensivo della durata di cinque giorni rivolto a venti professionisti di laboratori medici provenienti da Freetown e dalle province. L'iniziativa ha l'obiettivo di migliorare la precisione e l'efficacia della diagnosi della malaria nel Paese. Lo riferisce Sierraloaded.",
   "more": [
    "La malaria è una malattia infettiva parassitaria trasmessa dalle zanzare del genere Anopheles, particolarmente diffusa nelle aree tropicali e subtropicali. Una diagnosi tempestiva e accurata rappresenta uno strumento fondamentale per ridurre la mortalità e garantire un trattamento farmacologico mirato ed efficace ai pazienti affetti."
   ],
