   "lead": "Un gruppo di scienziati ed eticisti planetari olandesi, francesi e statunitensi ha pubblicato un articolo di opinione sulla rivista Eos, avvertendo che la trasformazione di Marte in un mondo simile alla Terra potrebbe distruggere in modo irreversibile le prove scientifiche sulla storia del pianeta e sulla possibile presenza passata di vita extraterrestri prima che venga pienamente esplorato. Lo riferisce Phys.org – Spazio.",
