   "orig": "Hong Kong ranks second in Asian pension systems, behind Singapore, as ageing tests retirement",
   "lead": "Hong Kong si conferma tra i migliori sistemi previdenziali in Asia, posizionandosi al secondo posto dietro a Singapore in una classifica regionale che precede Malaysia, Cina continentale, Taiwan, Giappone e Corea del Sud. Secondo il rapporto annuale del Marsh CFA Institute, la città ha ottenuto un punteggio di 71,2 e si colloca al sedicesimo posto su cinquantacinque sistemi a livello globale. Lo riferisce South China Morning Post – Economia.",
