   "lead": "Un eventuale tetto al prezzo del gas fissato al di sotto dei sessanta euro consentirebbe di ridurre le bollette di circa tre centesimi al kilowattora ai prezzi attuali. Tuttavia, una parte dei costi verrebbe sostenuta direttamente dai consumatori attraverso l'aumento degli oneri di sistema. Lo riferisce la Repubblica – Economia.",
