   "lead": "Il pastificio Rummo di Benevento ha dovuto interrompere la produzione a causa dell'impossibilità di ricevere camion e cisterne, avendo esaurito le scorte di magazzino. Il presidente e amministratore delegato ha spiegato che la concessione di aumenti agli autotrasportatori non è stata sufficiente a risolvere le criticità logistiche, che interessano anche la Puglia. Lo riferisce la Repubblica – Economia.",
