   "titolo": "Le aziende alle prese con l'obbligo di registrazione IVA nonostante la promessa di innalzamento della soglia",
   "orig": "Firms to decide whether to remain VAT-registered",
   "lead": "Le imprese continuano a essere obbligate a registrarsi ai fini dell'imposta sul valore aggiunto quando il fatturato annuo supera i duecentomila dollari, nonostante fosse stato promesso l'innalzamento della soglia a trecentocentomila dollari. Lo riferisce Barbados Today.",
   "more": [
    "Le soglie di fatturato per la registrazione fiscale obbligatorie influenzano gli adempimenti burocratici e la competitività delle piccole e medie imprese nei sistemi tributari nazionali."
   ],
