   "id": "z5a204e12",
   "sez": "mondo",
   "titolo": "Il Dipartimento della Giustizia incrimina ventotto persone per reati elettorali in California",
   "orig": "DOJ charges 28 in California with voting crimes as election tensions escalate",
   "lead": "Il Dipartimento della Giustizia degli Stati Uniti ha incriminato ventotto persone in California per presunti reati elettorali, nel quadro di un clima di crescente tensione politica nel Paese. Contestualmente, i legali del governo federale hanno presentato una richiesta d'urgenza a un tribunale federale per bloccare lo spoglio delle schede inviate da elettori presenti nei registri elettorali che le autorità federali ritengono non abbiano la cittadinanza americana. L'iniziativa giudiziaria si inserisce nelle polemiche sull'integrità del voto e sui controlli di regolarità. Lo riferisce NPR.",
   "more": [
    "La regolamentazione delle procedure di voto negli Stati Uniti è gestita principalmente dai singoli Stati federati. Le controversie sulle liste elettorali e sui requisiti di cittadinanza vedono frequentemente l'intervento delle corti federali per verificare la conformità con la legge elettorale federale."
   ],
