   "id": "ze3fc4fdf",
   "sez": "prima",
   "titolo": "Epidemia di Ebola in Kenya: salgono a otto i casi e gli Usa sconsigliano i viaggi",
   "orig": "Pipisu community strengthens disaster preparedness through simulation exercise",
   "lead": "Il Ministero della Salute del Kenya ha confermato un nuovo contagio da virus Ebola, portando a otto il totale dei casi registrati nel Paese. Le autorità hanno dichiarato l'epidemia di ceppo Bundibugyo come patologia altamente pericolosa, introducendo norme vincolanti su tracciamento, quarantena e sepolture sicure. A seguito della diffusione del virus, il Dipartimento di Stato degli Stati Uniti ha innalzato a livello tre l'allerta viaggi per il Kenya, invitando i propri cittadini a riconsiderare i trasferimenti verso la nazione africana per motivi sanitari.",
   "more": [
    "Il virus Ebola provoca febbri emorragiche gravi ed è caratterizzato da un'elevata letalità. Il ceppo Bundibugyo è una delle varianti note del virus; il contenimento delle epidemie richiede un tempestivo tracciamento dei contatti, l'isolamento dei pazienti infetti e rigide misure di biosicurezza negli ospedali."
   ],
