   "id": "zd9965ddb",
   "sez": "sport",
   "titolo": "Elina Svitolina annuncia la separazione da Gaël Monfils a causa del peso emotivo della guerra",
   "orig": "Tennis star Svitolina says emotional toll of Ukraine war led to Monfils separation",
   "lead": "La tennista ucraina Elina Svitolina, numero sei della classifica mondiale, ha annunciato la separazione dal marito e collega francese Gaël Monfils. La coppia, sposata dal 2021 e con una figlia, si è divisa a causa dell'impatto emotivo e psicologico provocato dalla guerra in Ucraina. Svitolina ha spiegato sui social network che le sofferenze legate al conflitto nel proprio Paese d'origine l'hanno portata a dover ritrovare se stessa, ponendo fine al matrimonio con il tennista transalpino dopo anni di carriera vissuti insieme nel circuito professionale.",
   "more": [
    "La tennista Elina Svitolina e Gaël Monfils rappresentavano una delle coppie più note dello sport internazionale. Fin dall'inizio dell'invasione russa nel 2022, l'atleta ucraina ha utilizzato la propria visibilità pubblica per sensibilizzare l'opinione mondiale sulle conseguenze umane del conflitto nel suo Paese."
   ],
