   "id": "z2685458a",
   "sez": "cultura",
   "titolo": "Il regista Charles Burnett presenta la versione restaurata del suo film sulla classe operaia afroamericana",
   "orig": "‘Sometimes it’s not perfect, but it works’: film-maker Charles Burnett on his chronicling of Black working-class life",
   "lead": "Il regista statunitense Charles Burnett ha presentato la versione restaurata del suo film del 1983 \"My Brother's Wedding\", ambientato nel quartiere South Central di Los Angeles. Il cineasta, riconosciuto come uno dei principali narratori della vita della classe lavoratrice afroamericana, ha raccontato i dilemmi personali e le ispirazioni reali che hanno guidato la realizzazione dell'opera. La riproposta della pellicola consente a un nuovo pubblico di riscoprire il valore sociale e artistico di un cinema indipendente incentrato sulla quotidianità e sulle complesse dinamiche comunitarie statunitensi.",
   "more": [
    "Charles Burnett è un importante esponente della \"L.A. Rebellion\", un movimento di registi afroamericani emerso alla UCLA tra gli anni Settanta e Ottanta. Il loro cinema si caratterizza per il ritratto realistico delle comunità urbane afroamericane, lontano dagli stereotipi delle produzioni commerciali hollywoodiane."
   ],
