   "id": "z79cbbcbc",
   "sez": "salute",
   "titolo": "Nuove linee guida sanitarie nel Regno Unito sugli spazi riservati in base al sesso biologico",
   "orig": "New NHS guidance on single sex spaces: what will it mean for staff?",
   "lead": "Il servizio sanitario inglese NHS ha pubblicato nuove linee guida sull'utilizzo degli spazi riservati a un solo sesso nelle strutture ospedaliere, stabilendo che servizi igienici, spogliatoi e reparti debbano essere fruiti in base al sesso biologico e non all'identità di genere. Le disposizioni si applicano sia ai pazienti sia al personale sanitario, imponendo alle dirigenze sanitarie di valutare l'adeguamento delle infrastrutture esistenti. Le autorità hanno precisato che gli eventuali costi per le modifiche dovranno essere riallocati prioritariamente all'interno dei bilanci ordinari dei singoli trust sanitarie.",
   "more": [
    "La gestione degli spazi monosessuali nel settore pubblico britannico è al centro di un ampio dibattito giuridico ed etico. Le normative puntano a bilanciare la tutela della privacy e della sicurezza biologica con la garanzia di accesso ai servizi per tutti gli utenti."
   ],
