   "id": "z56476f23",
   "sez": "dibattito",
   "titolo": "Il governo decide l'invio di militari a Milano e valuta nuove misure di prevenzione per i minori",
   "orig": "Il governo invia altri 500 soldati con potere di polizia a Milano. Fermo preventivo per i minori",
   "lead": "Il governo italiano ha stabilito l'invio di cinquecento militari con poteri di polizia a Milano e l'introduzione del fermo preventivo per i minori, oltre all'inasprimento delle pene per il reato di danneggiamento aggravato. Le decisioni sono giunte durante un vertice a Palazzo Chigi presieduto dalla premier Giorgia Meloni, promosso a seguito dei recenti scontri di piazza, dei saccheggi e delle devastazioni avvenuti nel capoluogo lombardo. Secondo l'esecutivo la misura garantisce una risposta ferma per tutelare l'ordine pubblico, mentre dal Viminale e dalle forze di polizia sono emersi inviti alla cautela sull'estensione dei poteri ai militari.",
   "more": [
    "L'impiego dell'Esercito in compiti di pubblica sicurezza in Italia è regolato dall'operazione \"Strade Sicure\", avviata nel 2008. Normalmente i militari affiancano le forze dell'ordine nella vigilanza di obiettivi sensibili. L'attribuzione di poteri diretti di polizia giudiziaria o d'intervento e l'applicazione di misure preventive verso i minorenni richiedono modifiche legislative che sollevano discussioni sull'equilibrio tra sicurezza e garanzie costituzionali."
   ],
