   "id": "zb94ea549",
   "sez": "manga",
   "titolo": "Pierrot Films realizzerà le animazioni per il sequel di Yona of the Dawn",
   "orig": "Pierrot Films Animates Yona of the Dawn Anime's Sequel",
   "lead": "Lo studio Pierrot Films realizzerà l'animazione del seguito della serie anime \"Yona of the Dawn\". L'annuncio della produzione del nuovo adattamento era stato dato lo scorso dicembre in concomitanza con la conclusione del manga originale. Gli appassionati della saga fantasy hanno così ricevuto la conferma formale della casa di produzione incaricata dei lavori di animazione, segnando il ritorno sul piccolo schermo delle avventure della principessa Yona dopo una lunga attesa da parte dei fan del franchise nipponico.",
   "more": [
    "Pierrot è uno storico studio di animazione giapponese, celebre per aver prodotto serie di grande successo internazionale. Il prosieguo di un adattamento anime dopo la conclusione del manga rappresenta una prassi frequente nell'industria dell'intrattenimento nipponica per valorizzare l'opera complessiva."
   ],
