   "id": "z73bd8a39",
   "sez": "spazio",
   "titolo": "La NASA pubblica la foto dell'effetto ottico noto come ventaglio arcobaleno anticrepuscolare",
   "orig": "APOD: 2026 October 20 – An Anticrepuscular Rainbow Fan",
   "lead": "La NASA ha pubblicato come Immagine Astronomica del Giorno un raro fenomeno ottico noto come ventaglio arcobaleno anticrepuscolare. L'immagine, selezionata e spiegata da astronomi professionisti nel portale educativo dell'agenzia spaziale statunitense, mostra lo spettacoloso effetto visivo generato dalla convergenza dei raggi solari verso il punto opposto al Sole nell'atmosfera terrestre. La pubblicazione offre uno spunto scientifico per illustrare le complesse interazioni della luce solare con le particelle d'acqua atmosferiche. Lo riferisce Nasa.",
   "more": [
    "I raggi anticrepuscolari sono fenomeni ottici atmosferici che appaiono convergere verso il punto anticrepuscolare, ovvero l'opposto del Sole nel cielo. Si verificano quando la luce solare filtrata da nubi o montagne attraversa l'atmosfera proiettando ombre parallele che per prospettiva sembrano unificarsi all'orizzonte."
   ],
