   "id": "zd8fb67b4",
   "sez": "ambiente",
   "titolo": "In Indonesia schierati oltre novemila agenti per le proteste degli studenti contro incendi e crisi azionaria",
   "orig": "Indonesia to deploy more than 9,000 security officers at protests marking Prabowo's two years in power",
   "lead": "In Indonesia le autorità hanno disposto il dispiegamento di oltre novemila agenti di sicurezza per gestire le manifestazioni di protesta organizzate in occasione dei due anni di governo del presidente Prabowo. Gli studenti universitari, tra cui quelli dell'Università dell'Indonesia, sono scesi in piazza per protestare contro i recenti incendi boschivi che stanno devastando il Paese e contro il forte crollo subito dal mercato azionario nazionale. Le forze dell'ordine presidiano la capitale e le principali città indonesiane per prevenire disordini durante gli cortei. Lo riferisce CNA.",
   "more": [
    "L'Indonesia affronta ciclicamente gravi crisi ambientali legate agli incendi nelle foreste tropicali e nelle torbiere, spesso causati dal disboscamento illegale. Le ripercussioni ecologiche si sommano alle oscillazioni dei mercati finanziari, alimentando le contestazioni studentesche nei confronti delle politiche governative."
   ],
