   "id": "zd1ff999d",
   "sez": "adolescenti",
   "titolo": "Riconoscimento all'attivista britannica Locita per le sue battaglie sull'integrazione scolastica",
   "orig": "'I didn't know our great-grandma did such amazing things'",
   "lead": "Le giovani giovanissime Elise e Renae hanno scoperto la straordinaria storia della loro bisnonna Locita, insignita della Medaglia d'Onore dall'Università di Manchester. L'onorificenza le è stata conferita per il lungo impegno nelle campagne a sostegno dell'integrazione e del successo scolastico dei bambini neri negli istituti britannici. Le due pronipoti hanno intervistato la donna per raccontare la sua battaglia civile, evidenziando l'importanza dell'istruzione e del contrasto alle discriminazioni etniche nell'ambiente educativo britannico per le nuove generazioni. Lo riferisce BBC Newsround.",
   "more": [
    "L'impegno per l'equità educativa punta a rimuovere le barriere sociali e culturali che possono ostacolare il rendimento scolastico delle minoranze. Il riconoscimento assegnato dall'Università di Manchester valorizza le iniziative dal basso che hanno contribuito all'inclusione nel sistema scolastico del Regno Unito."
   ],
