   "id": "z14b01d1b",
   "sez": "tech",
   "titolo": "Sciopero dei lavoratori Micron a Taiwan per la disputa sui premi aziendali",
   "orig": "Micron union in Taiwan to launch strike as bonus dispute escalates",
   "lead": "A Taoyuan, a Taiwan, il sindacato dei lavoratori dello stabilimento Micron Technology ha annunciato uno sciopero coincidente con l'incontro di mediazione tra l'azienda americana di semiconduttori e i rappresentanti del sito di Taichung. La protesta nasce dall'inasprimento della vertenza sui bonus dei dipendenti, con le rappresentanze sindacali che chiedono un miglioramento delle condizioni economiche e un'equa distribuzione dei premi aziendali. Lo sciopero rischia di creare disagi alle attività produttive dell'impianto taiwanese di microchip. Lo riferisce Daily Maverick.",
   "more": [
    "Micron Technology è uno dei principali produttori mondiali di chip di memoria. La produzione di semiconduttori a Taiwan costituisce uno snodo cruciale per la catena di approvvigionamento tecnologica globale, rendendo particolarmente delicate le controversie di lavoro negli stabilimenti dell'isola."
   ],
