   "sez": "cultura",
   "titolo": "L'attore Austin Abrams si racconta tra ruoli ad alta tensione e sfide cinematografiche",
   "orig": "Austin Abrams è l’uomo (qualunque) del momento",
   "lead": "L'attore americano Austin Abrams è al centro dell'attenzione cinematografica per i suoi ruoli in produzioni ad alta tensione, da \"Resident Evil\" fino all'opera claustrofobica \"Whalefall: Nella balena\". La rivista ripercorre la carriera dell'interprete, diventato il volto ideale per rappresentare personaggi ordinari catapultati in situazioni di estrema pressione e pericolo. Nel corso dell'intervista l'attore analizza la propria crescita professionale e il rapporto con l'interpretazione di personaggi complessi messi a dura prova in contesti narrativi drammatici. Lo riferisce Rolling Stone Italia.",
   "more": [
    "Il profilo dell'attore che interpreta personaggi comuni in situazioni straordinarie è un classico archetipo del cinema thriller e d'azione. Austin Abrams si è distinto nella nuova generazione di interpreti statunitensi per la sua capacità di rendere verosimili le reazioni umane allo stress emotivo."
   ],
