   "orig": "Detained Aung San Suu Kyi Receives UK Royal Package: Regime",
   "lead": "La giunta militare del Myanmar ha diffuso nuove immagini di Aung San Suu Kyi in occasione della consegna di libri e di una comunicazione diplomatica inviata da re Carlo III del Regno Unito. La leader politica, attualmente detenuta dal regime, ha ricevuto due volumi dedicati alla terra e due buste sigillate. Lo riferisce The Irrawaddy.",
