   "lead": "Gli operatori turistici della Thailandia esprimono forte preoccupazione per le prolungate proteste di piazza in corso in Francia. La situazione nel Paese europeo rischia di frenare i viaggi in entrata dalla popolazione europea verso la destinazione asiatica, aggravando un quadro già provato dalle tensioni persistenti in Medio Oriente. Lo riferisce Bangkok Post.",
