   "lead": "La divisione di ricerca Damo Academy del gruppo Alibaba ha annunciato che le spedizioni di chip basati sulla tecnologia open source RISC-V hanno superato i sei miliardi di unità. Il traguardo, comunicato durante una conferenza a Shenzhen, testimonia la spinta del gigante tecnologico verso l'intelligenza artificiale e i sistemi per l'automotive. Lo riferisce South China Morning Post – Tecnologia.",
