   "lead": "Con l'equinozio di primavera nell'emisfero settentrionale, il pianeta rosso celebra l'inizio di un nuovo anno marziano. Dalla superficie, il rover Curiosity della NASA continua a monitorare la situazione atmosferica e il movimento delle nubi durante la campagna di osservazione. Lo riferisce Nasa.",
