   "lead": "I giardini pluviali vengono indicati dagli esperti ambientali come una delle prime linee di difesa domestica contro il rischio di inondazioni, la cui frequenza ed estremità sono destinate ad aumentare a causa dei cambiamenti climatici. La soluzione verde consente di gestire efficacemente il deflusso delle acque piovane attorno agli edifici. Lo riferisce Euronews.",
