   "titolo": "Entrano in vigore le nuove regole europee sul diritto alla riparazione e sulla garanzia",
   "orig": "Diritto alla riparazione smartphone ed elettrodomestici, nuove regole dal 22 ottobre: cambia anche la garanzia",
   "lead": "A partire dal 22 ottobre debuttano le nuove disposizioni normative riguardanti il diritto alla riparazione per smartphone, elettrodomestici e dispositivi elettronici. Le modifiche introdotte mirano a favorire la manutenzione dei beni di consumo guasti e a modificare la disciplina delle garanzie commerciali. Lo riferisce Il Messaggero.",
   "more": [
    "Il diritto alla riparazione è un'iniziativa legislativa volta a contrastare l'obsolescenza programmata, imponendo ai produttori di garantire la disponibilità di pezzi di ricambio e di istruzioni tecniche per prolungare la vita utile dei prodotti."
   ],
