   "titolo": "Il giornalista Vakho Sanaia condannato a 30 giorni di detenzione per post sui social",
   "orig": "Journalist Vakho Sanaia Sentenced to 30 Days’ Detention in Proceedings Over Social Media Posts",
   "lead": "Il giornalista e conduttore televisivo Vakho Sanaia è stato condannato a trenta giorni di detenzione amministrativa dal tribunale di Tbilisi. La decisione è arrivata in seguito a una denuncia presentata dal ministero dell'Interno georgiano per alcuni messaggi pubblicati sui social network ritenuti offensivi nei confronti di esponenti del partito Sogno Georgiano. Si tratta del terzo provvedimento sanzionatorio emesso contro il reporter per simili contestazioni. Lo riferisce Civil.ge.",
   "more": [
    "Il sistema giudiziario georgiano prevede sanzioni amministrative e periodi di detenzione per reati minori legati alla diffamazione o a offese rivolte a figure pubbliche e istituzionali. Negli ultimi anni il clima politico nel Paese è stato caratterizzato da forti tensioni tra il governo e i media di opposizione, sollevando preoccupazioni internazionali sulla libertà di stampa e sulla tutela del dissenso politico."
   ],
