   "sez": "cultura",
   "titolo": "Francesco Totti presenta il nuovo libro al Teatro Brancaccio e parla del futuro della Roma",
   "orig": "Totti, il nuovo libro riempie il Brancaccio: «Ma io non l?ho letto». E si collega con Gasperini: «Ci vediamo a cena»",
   "lead": "L'ex capitano della Roma Francesco Totti ha presentato al Teatro Brancaccio il suo nuovo libro intitolato «Oltre», davanti a una folla di tifosi e ammiratori. Durante l'evento, caratterizzato da momenti di commozione e ironia, l'ex calciatore ha dichiarato di non aver letto l'opera e ha parlato del proprio rapporto con la società giallorossa, esprimendo la speranza che la proprietà dei Friedkin possa portare la squadra ai vertici, pur ammettendo divergenze di vedute. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "Il Teatro Brancaccio di Roma è uno storico palcoscenico della capitale, spesso utilizzato per eventi culturali, spettacoli teatrali e presentazioni editoriali di grande richiamo pubblico. La figura di Francesco Totti continua a rappresentare un punto di riferimento simbolico per i tifosi della squadra giallorossa, legando la sua popolarità a iniziative editoriali e mediatiche sulla sua lunga carriera sportiva."
   ],
