   "sez": "ingegneria",
   "titolo": "L'arena di Denver sarà sottoposta a un piano di ampliamento da 135 milioni di dollari",
   "orig": "Denver Arena to Undergo $135M in Phased Updates, and Other News",
   "lead": "Il palazzetto dello sport di Denver, sede delle squadre dei Denver Nuggets e dei Colorado Avalanche, sarà oggetto di un programma di ampliamento del valore di 135 milioni di dollari. L'intervento edilizio si svolgerà in modo graduale nell'arco di due anni, secondo quanto annunciato dai rappresentanti di Kroenke Sports & Entertainment, la società proprietaria sia delle franchigie sportive sia della struttura situata nel centro della città statunitense. Lo riferisce Engineering News-Record.",
   "more": [
    "I grandi impianti sportivi polifunzionali negli Stati Uniti affrontano periodicamente interventi di ammodernamento strutturale per migliorare l'esperienza degli spettatori, incrementare la capacità di accoglienza e adeguare gli spazi agli standard commerciali e tecnologici moderni. Questi progetti richiedono complessi piani di ingegneria e cantierizzazione per consentire lo svolgimento degli eventi sportivi programmati."
   ],
