   "titolo": "Seconda ondata di occupazioni nei licei di Roma: alta tensione al Rossellini",
   "orig": "Roma, occupati altri cinque licei. Alta tensione al Rossellini. «Pochi e col volto coperto»",
   "lead": "Sulla scia delle proteste del fine settimana, è iniziata una nuova ondata di occupazioni nelle scuole superiori di Roma, la seconda dall'inizio dell'anno scolastico. La situazione ha fatto registrare momenti di alta tensione in particolare al liceo Rossellini, dove le proteste studentesche sono state condotte da gruppi definiti ristretti e con il volto coperto. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "Le occupazioni studentesche rappresentano una forma di protesta ricorrente nelle scuole superiori italiane, spesso organizzate per rivendicare interventi sull'edilizia scolastica, riforme della didattica o per esprimere solidarietà su temi politici e sociali. Tali iniziative aprono regolarmente un dibattito pubblico tra il diritto dei giovani alla manifestazione e le regole di legalità e sicurezza all'interno degli istituti scolastici."
   ],
