   "sez": "sport",
   "titolo": "I Tampa Bay Rays battono i Cleveland Guardians e si qualificano alle World Series",
   "orig": "World Series will have first-time champion as Rays set up showdown with Brewers",
   "lead": "I Tampa Bay Rays hanno sconfitto i Cleveland Guardians con il punteggio di 7-3 in gara 6, aggiudicandosi la finale della American League in sei partite e conquistando l'accesso alle World Series per la terza volta nei 29 anni di storia della franchigia. La vittoria decisiva è stata costruita grazie a una solida prova di montuolo del lanciatore partente Freddy Peralta e ai fuoricampo da due punti battuti da Junior Caminero e Yandy Díaz. Nelle World Series i Rays affronteranno i Milwaukee Brewers. Lo riferisce The Guardian.",
   "more": [
    "Le World Series rappresentano la serie finale del campionato della Major League Baseball (MLB) nordamericana, disputata ogni anno in autunno tra la squadra vincitrice dell'American League e quella della National League. La qualificazione di franchigie che non hanno mai vinto il titolo offre una straordinaria occasione storica per rinnovare l'albo d'oro del baseball professionistico statunitense."
   ],
