   "sez": "spazio",
   "titolo": "La Corea del Sud pianifica il lancio di satelliti militari con il razzo nazionale Nuri nel 2031",
   "orig": "S. Korea to launch military satellites aboard homegrown Nuri rocket in 2031",
   "lead": "La Corea del Sud ha programmato per il 2031 il lancio di satelliti militari per la ricognizione utilizzando il vettore spaziale nazionale Nuri. Il progetto rientra nei piani strategici di sviluppo tecnologico e spaziale del Paese asiatico. Lo riferisce Yonhap.",
   "more": [
    "Il razzo Nuri è il primo veicolo di lancio spaziale interamente sviluppato e costruito in Corea del Sud, progettato per trasportare satelliti in orbita terrestre bassa. Lo sviluppo di vettori spaziali autonomi consente ai governi di acquisire capacità indipendenti sia per la ricerca scientifica sia per le telecomunicazioni e la sicurezza nazionale."
   ],
