   "id": "z5ae2072e",
   "sez": "cultura",
   "titolo": "Giornalisti e leader dei media celebrano la figura di Dele Giwa durante la presentazione di un libro",
   "orig": "Journalists, media leaders honour Dele Giwa at book unveiling",
   "lead": "Giornalisti e importanti esponenti del settore dei media si sono riuniti per onorare la memoria di Dele Giwa in occasione della presentazione di un libro a lui dedicato. L'ex collega Ekpu ha spiegato che l'opera editoriale è stata concepita per preservare l'eredità del giornalista e richiamare l'attenzione sull'importanza duratura del giornalismo d'inchiesta, della verità e della responsabilità civile. Lo riferisce Premium Times.",
   "more": [
    "Dele Giwa è stato un noto giornalista investigativo nigeriano, fondatore della rivista Newswatch, la cui tragica scomparsa avvenuta negli anni ottanta è diventata un simbolo della lotta per la libertà di stampa e del rischio affrontato dai reporter che denunciano la corruzione e gli abusi di potere."
   ],
