   "id": "z728d6383",
   "sez": "economia",
   "titolo": "Nuova minaccia per le esportazioni di pollame dal Brasile dopo la scoperta di una malattia presso un fornitore",
   "orig": "Brazil poultry exports face fresh threat after disease detected at MBRF supplier",
   "lead": "Le esportazioni di carne avicola dal Brasile affrontano una nuova minaccia commerciale in seguito alla rilevazione della malattia di Newcastle presso uno stabilimento di un fornitore della MBRF. La patologia virale altamente contagiosa colpisce in modo grave i sistemi respiratorio, nervoso e digestivo degli uccelli. Lo riferisce The Straits Times.",
   "more": [
    "La malattia di Newcastle è un'infezione virale che colpisce gli uccelli domestici e selvatici, comportando restrizioni veterinarie internazionali molto rigorose per impedire la diffusione del contagio attraverso il commercio di prodotti alimentari e avicoli. Il Brasile è uno dei maggiori esportatori mondiali di carne di pollo e la scoperta di focolai sanitari attiva immediatamente blocchi all'importazione da parte dei Paesi acquirenti."
   ],
