   "id": "z723b7d61",
   "sez": "dibattito",
   "titolo": "Addio al carro armato franco-tedesco: si ferma il progetto del blindato europeo",
   "orig": "Addio al carro armato del futuro franco-tedesco, difesa comune europea sempre più lontana",
   "lead": "Il progetto per la realizzazione del carro armato del futuro destinato a sostituire i blindati Leclerc è stato interrotto a causa dei dissidi tra Francia e Germania. Dopo il fallimento del programma congiunto per il caccia militare Fcas, si arena così un'altra ambiziosa iniziativa industriale militare, allontanando ulteriormente l'obiettivo di una difesa comune europea. Lo riferisce Il Messaggero – Tecnologia.",
   "more": [
    "I programmi di cooperazione industriale militare tra governi europei affrontano spesso ostacoli legati alla divisione dei carichi di lavoro industriali, ai diversi requisiti strategici delle forze armate nazionali e alla protezione delle rispettive tecnologie nazionali. Il settore dei mezzi corazzati pesanti richiede enormi investimenti in ricerca e sviluppo, rendendo complessi gli accordi bilaterali tra partner di pari peso economico come Parigi e Berlino."
   ],
