   "sez": "dibattito",
   "titolo": "Proteste giovanili in Albania, l'ex deputata Mimoza Hafizi: «Inaccettabile che la polizia insegua e picchi i quattordicenni»",
   "orig": "Pedagogia Mimoza Hafizi: Është e papranueshme që policia të ndjekë dhe të rrahë 14-vjeçarët",
   "lead": "Nel corso di un dibattito televisivo trasmesso da Euronews Albania, la docente ebrea ed ex deputata socialista Mimoza Hafizi ha commentato le recenti proteste definendole un'espressione del legittimo scontento di studenti e giovani di fronte alla mancanza di risposte da parte della politica. L'ex parlamentare ha definito del tutto inaccettabile che le forze di polizia arrivino a inseguire e picchiare i minori coinvolti nelle manifestazioni. Lo riferisce Euronews Albania.",
   "more": [
    "Le proteste giovanili nei Paesi dell'Europa orientale e balcanica spesso mettono in luce tensioni profonde tra le nuove generazioni e le istituzioni statali riguardo alla gestione dell'ordine pubblico e alla tutela dei diritti civili. L'uso della forza da parte delle autorità di polizia contro i manifestanti minorenni suscita regolarmente accesi dibattiti politici e costituzionali sulla proporzionalità degli interventi repressivi."
   ],
