   "id": "z7c001f54",
   "sez": "spazio",
   "titolo": "Un nuovo modello tridimensionale svela la complessità chimica nelle fucine stellari",
   "orig": "The Chemistry in Stellar Nurseries is Complex, and a New 3D Model Highlights It",
   "lead": "I ricercatori hanno sviluppato un innovativo modello tridimensionale focalizzato sulla Barra di Orione, una specifica struttura della regione di formazione stellare della Nebulosa di Orione. Il modello, realizzato a Vancouver, si allinea con le osservazioni del telescopio spaziale James Webb e spiega come la struttura irregolare delle nubi molecolari crei zone d'ombra in grado di influenzare l'astrochimica locale, guidata dall'interazione tra le radiazioni delle giovani stelle e le nubi stesse. Lo riferisce Universe Today.",
   "more": [
    "Le regioni di formazione stellare, note anche come vivai stellari, sono immense nubi di gas e polveri interstellari composte principalmente da idrogeno molecolare ed elio. Quando le giovani stelle si accendono, emettono intense radiazioni che riscaldano, ionizzano e scolpiscono l'ambiente circostante, dando origine a complesse reazioni chimiche e molecolari che gli astronomi studiano per comprendere l'evoluzione cosmica."
   ],
   "fonti": [
    {
     "n": "Universe Today",
     "p": "XX",
     "c": "Vancouver",
     "u": "https://www.universetoday.com/articles/the-chemistry-in-stellar-nurseries-is-complex-and-a-new-3d-model-highlights-it",
     "angolo": "",
     "atlas": "Canada",
     "t": "2026-10-19T22:09+00:00"
    }
   ],
   "data": "20 ott",
