   "lead": "Gli atleti di tennis tavolo di Hong Kong impegnati a Nagoya hanno ottenuto diverse medaglie di bronzo durante i Giochi Para-Asiatici. La delegazione dell'area amministrativa speciale si è garantita i piazzamenti sul podio al termine delle semifinali disputate allo Sky Hall Toyota. Lo riferisce RTHK.",
