   "lead": "La festività di Dussehra, celebrata a Mumbai, commemora il trionfo del bene sul male attraverso preghiere collettive, riunioni familiari e la tradizionale combustione di grandi effigi. La ricorrenza rappresenta un momento di riconciliazione e di rinnovamento personale. Lo riferisce Times of India.",
