   "lead": "In occasione della festività del Thanksgiving, il direttore responsabile Jamila Robinson ha pubblicato a New York una riflessione editoriale dedicata alle tradizioni culinarie che uniscono le famiglie intorno alla tavola. Lo riferisce Bon Appétit.",
