   "sez": "spazio",
   "titolo": "Lo sciame meteorico delle Orionidi raggiunge il suo culmine",
   "orig": "How to see the Orionid meteor shower",
   "lead": "Lo sciame meteorico autunnale delle Orionidi entra nella sua fase di massima visibilità, offrendo agli appassionati di astronomia la possibilità di osservare tra i dieci e i venti frammenti luminosi ogni ora nel cielo notturno. Il fenomeno, generato dai residui lasciati lungo l'orbita dalla cometa di Halley, rimarrà attivo fino al 7 novembre. Le condizioni di osservazione risultano particolarmente favorevoli nelle prime ore del mattino del 22 ottobre, grazie al tramonto tempestivo della Luna che garantisce l'oscurità necessaria per scorgere le scie celesti in tutto l'emisfero.",
   "more": [
    "Le Orionidi sono uno dei passaggi meteorici annuali più noti, originati dall'intersezione dell'orbita terrestre con la scia di polveri e detriti della cometa di Halley. Quando questi corpuscoli penetrano ad altissima velocità nell'atmosfera terrestre, l'attrito li disintegra creando le caratteristiche tracce luminose visibili a occhio nudo."
   ],
