   "sez": "sport",
   "titolo": "Portogallo, trenta giorni di squalifica per Cristiano Ronaldo",
   "orig": "Cristiano Ronaldo écope de 30 jours de suspension et d'une amende de 255 euros",
   "lead": "La Federazione calcistica portoghese ha inflitto una squalifica di trenta giorni e una sanzione pecuniaria di 255 euro all'attaccante Cristiano Ronaldo. La commissione disciplinare ha confermato il provvedimento dopo l'istruttoria aperta a seguito dell'abbandono improvviso del ritiro della nazionale, avvenuto a fine settembre durante gli impegni di UEFA Nations League. Il quarantunenne capitano lusitano aveva lasciato la squadra dopo un acceso contrasto con il commissario tecnico Jorge Jesus, accusato dal calciatore di non aver rispettato gli accordi sul minutaggio e sul suo effettivo impiego sul terreno di gioco.",
   "more": [
    "La Federazione calcistica del Portogallo (FPF) governa le selezioni nazionali e applica il codice di giustizia sportiva sui propri tesserati. Gli organi disciplinari federali hanno il potere di sanzionare comportamenti contrari ai doveri di lealtà, compreso l'abbandono ingiustificato dei raduni ufficiali."
   ],
